@model CreateQuizViewModel
@{ ViewData["Title"] = "Create quiz"; }
<section class="auth-wrap"><div class="card auth-card"><h1>Create quiz</h1><form asp-action="CreateQuiz" method="post" class="form">@Html.AntiForgeryToken()<label asp-for="CourseId">Course</label><select asp-for="CourseId" asp-items="Model.Courses"></select><span asp-validation-for="CourseId" class="field-error"></span><label asp-for="Title"></label><input asp-for="Title" /><span asp-validation-for="Title" class="field-error"></span><label asp-for="Summary"></label><textarea asp-for="Summary" rows="3"></textarea><span asp-validation-for="Summary" class="field-error"></span><label asp-for="PassMarkPercent"></label><input asp-for="PassMarkPercent" type="number" min="1" max="100" /><span asp-validation-for="PassMarkPercent" class="field-error"></span><div class="row top-gap"><a asp-action="Index" class="btn ghost">Back</a><button type="submit" class="btn">Save quiz</button></div></form></div></section>
@section Scripts { <partial name="_ValidationScriptsPartial" /> }
